const cv = $('Load CV').first().json.cv;
const SKIP_STATUS = ['pack_ready', 'applied', 'rejected', 'ignored'];
const MAX = 10; 

const rows = $input.all().map(i => i.json)
  .filter(j => j.title && String(j.title).trim() !== '')
  .filter(j => j.ai_analyzed === true)
  .filter(j => ['apply', 'maybe'].includes(j.ai_recommendation))
  .filter(j => !SKIP_STATUS.includes(j.status))
  .filter(j => !j.pack_cv_file)
  .sort((a, b) => (b.relevance_score || 0) - (a.relevance_score || 0))
  .slice(0, MAX);

return rows.map(job => ({ json: { job, cv } }));

const GROUP_LABEL = { cloud: 'Cloud & Infrastructure', cicd: 'CI/CD & Version Control', containers: 'Containers', systems: 'Systems', networking: 'Networking', support: 'Support & Troubleshooting', web: 'Web & CMS', databases: 'Databases', scripting: 'Scripting' };
const TRACK_MAP = { devops_cloud: 'devops', linux_infra: 'devops', network: 'it_support', it_support: 'it_support', wordpress: 'wordpress' };
const SUFFIX = { basic: ' (basic)', exposure: ' (exposure)', learning: ' (learning)' };
const BUDGET = 4300;

const norm = s => String(s || '').toLowerCase().replace(/[\/\-]/g, ' ');
const rx = s => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const slug = s => String(s || '').normalize('NFKD').replace(/[^\w\s-]/g, '').trim().replace(/\s+/g, '-').toLowerCase().slice(0, 40);
const list = a => a.length < 2 ? a.join('') : a.slice(0, -1).join(', ') + ' and ' + a[a.length - 1];
const lcFirst = t => t.charAt(0).toLowerCase() + t.slice(1);
const sentence = t => /[.!?]$/.test(t) ? t : t + '.';

function matcher(job) {
  const text = norm([job.title, job.description, job.required_skills, job.matched_keywords].join(' '));
  return term => {
    const e = rx(norm(term).trim());
    return !!e && new RegExp('(^|[^a-z0-9])' + e + '([^a-z0-9]|$)').test(text);
  };
}

function selectLines(job, cv) {
  const has = matcher(job);
  const track = TRACK_MAP[job.job_category] || 'devops';
  const maxProjects = track === 'devops' ? 4 : 3;
  const inTrack = b => (b.tracks || []).includes(track);
  const pick = b => ({ id: b.id, text: (b.variants && b.variants[track]) || b.text, score: 1 + 2 * (b.tags || []).filter(has).length });

  const experience = cv.experience.map(e => ({
    title: e.title, org: e.org, dates: e.dates,
    bullets: e.bullets.filter(inTrack).map(pick).sort((a, b) => b.score - a.score).slice(0, 4)
  })).filter(e => e.bullets.length);

  const projects = cv.projects.map(p => {
    const bullets = p.bullets.filter(inTrack).map(pick).sort((a, b) => b.score - a.score);
    return { name: p.name, link: p.link, bullets, total: bullets.reduce((s, b) => s + b.score, 0) };
  }).filter(p => p.bullets.length).sort((a, b) => b.total - a.total).slice(0, maxProjects);

  const ORDER = {
    devops: ['cloud', 'cicd', 'containers', 'systems', 'networking', 'databases', 'scripting', 'web'],
    it_support: ['systems', 'networking', 'support', 'cloud', 'containers', 'cicd', 'databases', 'scripting', 'web'],
    wordpress: ['web', 'databases', 'systems', 'cicd', 'containers', 'cloud', 'scripting']
  }[track];
  const matchedSkill = s => has(s.name) || s.name.toLowerCase().split(/[,()\/]\s*/).some(has);
  const trackSkills = cv.skills.filter(s => (s.tracks || []).includes(track));
  const skills_grouped = ORDER.map(g => ({
    label: GROUP_LABEL[g],
    items: trackSkills.filter(s => s.group === g)
      .sort((a, b) => Number(matchedSkill(b)) - Number(matchedSkill(a)))
      .map(s => s.name + (SUFFIX[s.level] || ''))
  })).filter(g => g.items.length);

  return {
    track, experience, projects, skills_grouped,
    headline: cv.headlines[track], summary: cv.summaries[track],
    contact: cv.contact, education: cv.education || [],
    availability: (cv.availability || {})[track] || ''
  };
}

function buildHtml(d) {
  const c = d.contact || {};
  const url = s => /^https?:\/\//.test(s) ? s : 'https://' + s;
  const link = s => s ? '<a href="' + esc(url(s)) + '">' + esc(s) + '</a>' : '';

  let exp = d.experience.map(e => ({ ...e, bullets: e.bullets.slice(0, 3) }));
  let proj = d.projects.map((p, i) => ({ ...p, bullets: p.bullets.slice(0, i === 0 ? 3 : 2) }));
  const size = () => d.summary.length +
    d.skills_grouped.reduce((n, g) => n + g.label.length + g.items.join(', ').length + 4, 0) +
    [...exp, ...proj].reduce((n, x) => n + 70 + x.bullets.reduce((m, b) => m + b.text.length + 20, 0), 0);
  while (size() > BUDGET) {
    const cands = [];
    [...exp, ...proj].forEach(x => { if (x.bullets.length > 1) x.bullets.forEach(b => cands.push({ x, b, i: cands.length })); });
    if (cands.length) {
      cands.sort((a, b) => a.b.score - b.b.score || b.i - a.i);
      cands[0].x.bullets = cands[0].x.bullets.filter(y => y !== cands[0].b);
    } else if (proj.length > 1) { proj.pop(); } else break;
  }

  const bullets = arr => '<ul>' + arr.map(b => '<li>' + esc(b.text) + '</li>').join('') + '</ul>';
  const entry = (l, r, bl) => '<div class="e"><div class="eh"><span><b>' + l + '</b></span><span class="m">' + r + '</span></div>' + (bl ? bullets(bl) : '') + '</div>';
  const sec = (t, body) => body ? '<h2>' + t + '</h2>' + body : '';

  const line1 = [esc(c.city), esc(c.email), esc(c.phone)].filter(Boolean).join(' &nbsp;•&nbsp; ');
  const line2 = [link(c.github), link(c.linkedin)].filter(Boolean).join(' &nbsp;•&nbsp; ');
  const skillsHtml = d.skills_grouped.map(g => '<p class="sk"><b>' + esc(g.label) + ':</b> ' + esc(g.items.join(', ')) + '</p>').join('');
  const expHtml = exp.map(e => entry(esc(e.title) + ', ' + esc(e.org), esc(e.dates), e.bullets)).join('');
  const projHtml = proj.map(p => entry(esc(p.name), link(p.link), p.bullets)).join('');
  const eduHtml = d.education.map(e => entry(esc(e.program) + ', ' + esc(e.school), esc([e.dates, e.note].filter(Boolean).join(' · ')), null)).join('');
  const middle = d.track === 'devops' ? sec('Projects', projHtml) + sec('Experience', expHtml) : sec('Experience', expHtml) + sec('Projects', projHtml);

  return `<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><title>${esc(c.name)} - CV</title>
<style>
@page { size: A4; margin: 11mm 13mm; }
* { -webkit-print-color-adjust: exact; print-color-adjust: exact; }
body { font-family: Carlito, Calibri, "Liberation Sans", Arial, sans-serif; font-size: 9.6pt; line-height: 1.3; color: #1a1a1a; margin: 0; }
a { color: inherit; text-decoration: none; }
h1 { font-size: 24pt; letter-spacing: 0.5px; margin: 0; color: #1f3a5f; text-align: center; }
.sub { font-size: 11pt; color: #444; margin: 1px 0 3px; text-align: center; }
.contact { font-size: 9pt; color: #333; margin-bottom: 4px; text-align: center; }
h2 { font-size: 10pt; letter-spacing: 1.2px; text-transform: uppercase; color: #1f3a5f; border-bottom: 1.2px solid #1f3a5f; margin: 9px 0 4px; padding-bottom: 1px; }
.e { margin-bottom: 4px; break-inside: avoid; }
.eh { display: flex; justify-content: space-between; align-items: baseline; gap: 12px; }
.m { font-size: 9pt; color: #555; white-space: nowrap; }
p { margin: 2px 0; }
.sk { margin: 1px 0; }
ul { margin: 2px 0 0 16px; padding: 0; }
li { margin: 1px 0; }
</style></head><body>
<h1>${esc(c.name)}</h1>
<div class="sub">${esc(d.headline)}</div>
<div class="contact">${line1}<br>${line2}</div>
${sec('Summary', '<p>' + esc(d.summary) + '</p>')}
${sec('Technical Skills', skillsHtml)}
${middle}
${sec('Education', eduHtml)}
${sec('Availability', d.availability ? '<p>' + esc(d.availability) + '</p>' : '')}
</body></html>`;
}

function buildMessage(d, job) {
  const has = matcher(job);
  const isWeak = s => /\((basic|exposure|learning)\)$/.test(s);
  const parts = s => s.split(/[,()]/).map(x => x.trim()).filter(Boolean);
  const groups = d.skills_grouped.filter(g => g.label !== 'Support & Troubleshooting');
  let skills = [];
  for (const g of groups) for (const s of g.items.filter(x => !isWeak(x))) {
    const m = parts(s).find(has);
    if (m && !skills.includes(m)) skills.push(m);
  }
  if (!skills.length) skills = groups.map(g => g.items.find(x => !isWeak(x))).filter(Boolean).map(s => parts(s)[0]).slice(0, 3);
  skills = skills.slice(0, 4);

  const all = [...d.projects, ...d.experience].flatMap(x => x.bullets);
  const top = all.reduce((best, b) => (!best || b.score > best.score) ? b : best, null);
  const cleanTitle = String(job.title).replace(/\s*[\(\[].*?[\)\]]/g, '').trim();
  const at = job.company ? ' at ' + job.company : '';
  const school = ((d.education[0] || {}).school || '').replace(/\s*\(.*\)/, '');
  const usesInternship = d.track === 'wordpress' || (top && /^exp/.test(top.id)) || skills.some(s => /wordpress|cpanel|html|css|bootstrap|php/i.test(s));
  const source = usesInternship ? 'my web development internship and personal projects' : 'personal projects';
  const body =
    'I am a Computer Science undergraduate at the ' + school + ', and I am applying for the ' + cleanTitle + ' position' + at + '. ' +
    'I have hands-on experience with ' + list(skills) + ', from ' + source + '. ' +
    (top ? 'For example, I ' + sentence(lcFirst(top.text)) + ' ' : '') +
    'My CV is attached, and I would welcome the chance to discuss the role.';
  const name = d.contact.name;
  return { cleanTitle, subject: 'Application – ' + cleanTitle + ' – ' + name, message: 'Dear Hiring Team,\n\n' + body + '\n\nBest regards,\n' + name };
}

const out = [];
const today = new Date().toISOString().slice(0, 10);
for (const item of $input.all()) {
  const { job, cv } = item.json;
  const d = selectLines(job, cv);
  const m = buildMessage(d, job);
  const html = buildHtml(d);

  const notes = [];
  if (JSON.stringify(cv.contact).includes('<fill')) notes.push('Contact placeholders still in master_cv.json');
  if (String(job.title).includes(' / ')) notes.push('Title lists several roles, so edit the first sentence');
  if (!(job.description && String(job.description).trim())) notes.push('No description, so the match is based on the title only');
  notes.push('Score ' + job.relevance_score + ', track ' + d.track + ', flags: ' + (job.red_flags || 'none'));

    const cv_file = 'S' + (job.relevance_score ?? 0) + '_job' + job.id + '_' + slug(job.company) + '_' + slug(m.cleanTitle) + '_' + d.track + '.pdf';
  const bin = await this.helpers.prepareBinaryData(Buffer.from(html, 'utf8'), 'index.html', 'text/html');
  out.push({
    json: { row_id: job.id, cv_file, subject: m.subject, message: m.message, notes: notes.join(' | '), packed_at: today, label: d.track + ': ' + job.title + ' @ ' + job.company,
            job_url: job.job_url, company: job.company, title: job.title, score: job.relevance_score, track: d.track },
    binary: { data: bin }
  });
}
return out;

const packs = $('Build Pack').all();
return $input.all().map((item, i) => ({
  json: { ...packs[i].json },
  binary: { pdf: item.binary.pdf }
}));

const out = [];
for (const item of $input.all()) {
  const j = item.json;
  const text = [
    'JOB: ' + j.title + ' @ ' + j.company,
    'SCORE: ' + j.score + '   CV TYPE: ' + j.track,
    'APPLY LINK: ' + j.job_url,
    'CV FILE TO UPLOAD: ' + j.cv_file,
    '',
    'NOTES: ' + j.notes,
    '',
    'SUBJECT: ' + j.subject,
    '',
    j.message
  ].join('\n');
  const note_file = j.cv_file.replace(/\.pdf$/, '.txt');
  const bin = await this.helpers.prepareBinaryData(Buffer.from(text, 'utf8'), note_file, 'text/plain');
  out.push({ json: { note_file }, binary: { data: bin } });
}
return out;
